using System.Text.Json;
using Dapper;
using Sigov.Application.Agro.PatrulhaMecanizada;
using Sigov.Application.Common;
using Sigov.Infrastructure.Agro.Sql;
using Sigov.Infrastructure.Persistence.Dapper;

namespace Sigov.Infrastructure.Agro.Repositories;

public sealed class AgroPatrulhaMecanizadaRepository : IAgroPatrulhaMecanizadaRepository
{
    private readonly DapperContext _context; public AgroPatrulhaMecanizadaRepository(DapperContext context)=>_context=context;
    public async Task<PagedResult<AgroMaquinaResponse>> ListarMaquinasAsync(long tenantId,long entidadeId,AgroMaquinaFiltro f,CancellationToken ct){const string data="select id,tenant_id TenantId,entidade_id EntidadeId,codigo,nome,tipo_maquina TipoMaquina,placa,horimetro_atual HorimetroAtual,odometro_atual OdometroAtual,situacao,ativo from sigov.agro_maquina where tenant_id=@TenantId and entidade_id=@EntidadeId and is_deleted=false and (@Situacao is null or situacao=@Situacao) and (@Busca is null or codigo ilike @Busca or nome ilike @Busca or placa ilike @Busca) order by nome limit @Limit offset @Offset"; const string count="select count(*) from sigov.agro_maquina where tenant_id=@TenantId and entidade_id=@EntidadeId and is_deleted=false and (@Situacao is null or situacao=@Situacao) and (@Busca is null or codigo ilike @Busca or nome ilike @Busca or placa ilike @Busca)"; return await Page<AgroMaquinaResponse>(data,count,tenantId,entidadeId,f,ct);}
    public async Task<AgroMaquinaResponse?> ObterMaquinaAsync(long tenantId,long entidadeId,long id,CancellationToken ct){const string sql="select id,tenant_id TenantId,entidade_id EntidadeId,codigo,nome,tipo_maquina TipoMaquina,placa,horimetro_atual HorimetroAtual,odometro_atual OdometroAtual,situacao,ativo from sigov.agro_maquina where tenant_id=@TenantId and entidade_id=@EntidadeId and id=@Id and is_deleted=false"; using var cn=_context.CreateConnection(); return await cn.QuerySingleOrDefaultAsync<AgroMaquinaResponse>(new CommandDefinition(sql,new{TenantId=tenantId,EntidadeId=entidadeId,Id=id},cancellationToken:ct));}
    public async Task<long> CriarMaquinaAsync(long tenantId,long entidadeId,long? usuarioId,AgroMaquinaCreateRequest r,CancellationToken ct){const string sql="insert into sigov.agro_maquina(tenant_id,entidade_id,patrimonio_bem_id,frota_veiculo_id,codigo,nome,tipo_maquina,placa,horimetro_atual,odometro_atual,situacao,observacao,ativo,created_by,correlation_id) values(@TenantId,@EntidadeId,@PatrimonioBemId,@FrotaVeiculoId,@Codigo,@Nome,@TipoMaquina,@Placa,@HorimetroAtual,@OdometroAtual,@Situacao,@Observacao,@Ativo,@UsuarioId,@CorrelationId) returning id"; using var cn=_context.CreateConnection(); var id=await cn.ExecuteScalarAsync<long>(new CommandDefinition(sql,new{TenantId=tenantId,EntidadeId=entidadeId,r.PatrimonioBemId,r.FrotaVeiculoId,r.Codigo,r.Nome,r.TipoMaquina,r.Placa,r.HorimetroAtual,r.OdometroAtual,r.Situacao,r.Observacao,r.Ativo,UsuarioId=usuarioId,CorrelationId=Guid.NewGuid()},cancellationToken:ct)); await Evento(cn,tenantId,entidadeId,null,usuarioId,"AgroMaquinaCriada","agro_maquina",id,ct); return id;}
    public async Task AtualizarMaquinaAsync(long tenantId,long entidadeId,long id,long? usuarioId,AgroMaquinaUpdateRequest r,CancellationToken ct){const string sql="update sigov.agro_maquina set patrimonio_bem_id=@PatrimonioBemId,frota_veiculo_id=@FrotaVeiculoId,codigo=@Codigo,nome=@Nome,tipo_maquina=@TipoMaquina,placa=@Placa,horimetro_atual=@HorimetroAtual,odometro_atual=@OdometroAtual,situacao=@Situacao,observacao=@Observacao,ativo=@Ativo,updated_at=now(),updated_by=@UsuarioId where tenant_id=@TenantId and entidade_id=@EntidadeId and id=@Id and is_deleted=false"; using var cn=_context.CreateConnection(); await cn.ExecuteAsync(new CommandDefinition(sql,new{TenantId=tenantId,EntidadeId=entidadeId,Id=id,r.PatrimonioBemId,r.FrotaVeiculoId,r.Codigo,r.Nome,r.TipoMaquina,r.Placa,r.HorimetroAtual,r.OdometroAtual,r.Situacao,r.Observacao,r.Ativo,UsuarioId=usuarioId},cancellationToken:ct));}
    public Task ExcluirMaquinaAsync(long tenantId,long entidadeId,long id,long? usuarioId,CancellationToken ct)=>Soft("sigov.agro_maquina",tenantId,entidadeId,id,usuarioId,ct);
    public async Task<PagedResult<AgroImplementoResponse>> ListarImplementosAsync(long tenantId,long entidadeId,AgroMaquinaFiltro f,CancellationToken ct){const string data="select id,tenant_id TenantId,entidade_id EntidadeId,maquina_id MaquinaId,codigo,nome,tipo_implemento TipoImplemento,situacao,ativo from sigov.agro_implemento where tenant_id=@TenantId and entidade_id=@EntidadeId and is_deleted=false order by nome limit @Limit offset @Offset"; const string count="select count(*) from sigov.agro_implemento where tenant_id=@TenantId and entidade_id=@EntidadeId and is_deleted=false"; return await Page<AgroImplementoResponse>(data,count,tenantId,entidadeId,f,ct);}
    public async Task<long> CriarImplementoAsync(long tenantId,long entidadeId,long? usuarioId,AgroImplementoCreateRequest r,CancellationToken ct){const string sql="insert into sigov.agro_implemento(tenant_id,entidade_id,maquina_id,codigo,nome,tipo_implemento,situacao,observacao,ativo,created_by,correlation_id) values(@TenantId,@EntidadeId,@MaquinaId,@Codigo,@Nome,@TipoImplemento,@Situacao,@Observacao,@Ativo,@UsuarioId,@CorrelationId) returning id"; using var cn=_context.CreateConnection(); var id=await cn.ExecuteScalarAsync<long>(new CommandDefinition(sql,new{TenantId=tenantId,EntidadeId=entidadeId,r.MaquinaId,r.Codigo,r.Nome,r.TipoImplemento,r.Situacao,r.Observacao,r.Ativo,UsuarioId=usuarioId,CorrelationId=Guid.NewGuid()},cancellationToken:ct)); await Evento(cn,tenantId,entidadeId,null,usuarioId,"AgroImplementoCriado","agro_implemento",id,ct); return id;}
    public async Task<PagedResult<AgroAgendaMaquinaResponse>> ListarAgendaAsync(long tenantId,long entidadeId,AgroMaquinaFiltro f,CancellationToken ct){const string data="select id,tenant_id TenantId,entidade_id EntidadeId,exercicio_id ExercicioId,maquina_id MaquinaId,servico_maquina_id ServicoMaquinaId,data_inicio DataInicio,data_fim DataFim,status,observacao from sigov.agro_agenda_maquina where tenant_id=@TenantId and entidade_id=@EntidadeId and is_deleted=false order by data_inicio desc limit @Limit offset @Offset"; const string count="select count(*) from sigov.agro_agenda_maquina where tenant_id=@TenantId and entidade_id=@EntidadeId and is_deleted=false"; return await Page<AgroAgendaMaquinaResponse>(data,count,tenantId,entidadeId,f,ct);}
    public async Task<long> CriarAgendaAsync(long tenantId,long entidadeId,long? exercicioId,long? usuarioId,AgroAgendaMaquinaCreateRequest r,CancellationToken ct){const string sql="insert into sigov.agro_agenda_maquina(tenant_id,entidade_id,exercicio_id,maquina_id,servico_maquina_id,data_inicio,data_fim,status,observacao,created_by,correlation_id) values(@TenantId,@EntidadeId,@ExercicioId,@MaquinaId,@ServicoMaquinaId,@DataInicio,@DataFim,@Status,@Observacao,@UsuarioId,@CorrelationId) returning id"; using var cn=_context.CreateConnection(); var id=await cn.ExecuteScalarAsync<long>(new CommandDefinition(sql,new{TenantId=tenantId,EntidadeId=entidadeId,ExercicioId=exercicioId,r.MaquinaId,r.ServicoMaquinaId,r.DataInicio,r.DataFim,r.Status,r.Observacao,UsuarioId=usuarioId,CorrelationId=Guid.NewGuid()},cancellationToken:ct)); await Evento(cn,tenantId,entidadeId,exercicioId,usuarioId,"AgroAgendaMaquinaCriada","agro_agenda_maquina",id,ct); return id;}
    public async Task<bool> ExisteConflitoAgendaAsync(long tenantId,long entidadeId,long maquinaId,DateTimeOffset inicio,DateTimeOffset fim,long? ignorarId,CancellationToken ct){using var cn=_context.CreateConnection(); return await cn.ExecuteScalarAsync<bool>(new CommandDefinition(AgroPatrulhaMecanizadaSql.AgendaConflito,new{TenantId=tenantId,EntidadeId=entidadeId,MaquinaId=maquinaId,DataInicio=inicio,DataFim=fim,IgnorarId=ignorarId},cancellationToken:ct));}
    public async Task<PagedResult<AgroServicoMaquinaResponse>> ListarServicosAsync(long tenantId,long entidadeId,AgroServicoMaquinaFiltro f,CancellationToken ct){const string data="select s.id,s.tenant_id TenantId,s.entidade_id EntidadeId,s.exercicio_id ExercicioId,s.produtor_id ProdutorId,s.propriedade_id PropriedadeId,s.maquina_id MaquinaId,s.implemento_id ImplementoId,s.numero,s.tipo_servico TipoServico,s.data_solicitacao DataSolicitacao,s.data_agendada DataAgendada,s.data_execucao DataExecucao,s.horas_trabalhadas HorasTrabalhadas,s.area_atendida_ha AreaAtendidaHa,s.valor_estimado ValorEstimado,s.valor_cobrado ValorCobrado,s.status,coalesce(left(p.nome,1)||'***','Produtor rural') ProdutorNomeMascarado from sigov.agro_servico_maquina s left join sigov.agro_produtor ap on ap.id=s.produtor_id and ap.tenant_id=s.tenant_id left join sigov.pessoa p on p.id=ap.pessoa_id where s.tenant_id=@TenantId and s.entidade_id=@EntidadeId and s.is_deleted=false and (@ProdutorId is null or s.produtor_id=@ProdutorId) and (@Status is null or s.status=@Status) order by s.created_at desc limit @Limit offset @Offset"; const string count="select count(*) from sigov.agro_servico_maquina s where s.tenant_id=@TenantId and s.entidade_id=@EntidadeId and s.is_deleted=false and (@ProdutorId is null or s.produtor_id=@ProdutorId) and (@Status is null or s.status=@Status)"; using var cn=_context.CreateConnection(); var args=new{TenantId=tenantId,EntidadeId=entidadeId,f.ProdutorId,Status=Empty(f.Status),Limit=f.PageSize,Offset=(f.Page-1)*f.PageSize}; var items=(await cn.QueryAsync<AgroServicoMaquinaResponse>(new CommandDefinition(data,args,cancellationToken:ct))).ToArray(); var total=await cn.ExecuteScalarAsync<long>(new CommandDefinition(count,args,cancellationToken:ct)); return new(items,f.Page,f.PageSize,total);}
    public async Task<AgroServicoMaquinaResponse?> ObterServicoAsync(long tenantId,long entidadeId,long id,CancellationToken ct){const string sql="select s.id,s.tenant_id TenantId,s.entidade_id EntidadeId,s.exercicio_id ExercicioId,s.produtor_id ProdutorId,s.propriedade_id PropriedadeId,s.maquina_id MaquinaId,s.implemento_id ImplementoId,s.numero,s.tipo_servico TipoServico,s.data_solicitacao DataSolicitacao,s.data_agendada DataAgendada,s.data_execucao DataExecucao,s.horas_trabalhadas HorasTrabalhadas,s.area_atendida_ha AreaAtendidaHa,s.valor_estimado ValorEstimado,s.valor_cobrado ValorCobrado,s.status,coalesce(left(p.nome,1)||'***','Produtor rural') ProdutorNomeMascarado from sigov.agro_servico_maquina s left join sigov.agro_produtor ap on ap.id=s.produtor_id and ap.tenant_id=s.tenant_id left join sigov.pessoa p on p.id=ap.pessoa_id where s.tenant_id=@TenantId and s.entidade_id=@EntidadeId and s.id=@Id and s.is_deleted=false"; using var cn=_context.CreateConnection(); return await cn.QuerySingleOrDefaultAsync<AgroServicoMaquinaResponse>(new CommandDefinition(sql,new{TenantId=tenantId,EntidadeId=entidadeId,Id=id},cancellationToken:ct));}
    public async Task<long> CriarServicoAsync(long tenantId,long entidadeId,long? exercicioId,long? usuarioId,AgroServicoMaquinaCreateRequest r,string numero,CancellationToken ct){const string sql="insert into sigov.agro_servico_maquina(tenant_id,entidade_id,exercicio_id,produtor_id,propriedade_id,maquina_id,implemento_id,numero,tipo_servico,data_agendada,valor_estimado,status,observacao,created_by,correlation_id) values(@TenantId,@EntidadeId,@ExercicioId,@ProdutorId,@PropriedadeId,@MaquinaId,@ImplementoId,@Numero,@TipoServico,@DataAgendada,@ValorEstimado,'SOLICITADO',@Observacao,@UsuarioId,@CorrelationId) returning id"; using var cn=_context.CreateConnection(); var id=await cn.ExecuteScalarAsync<long>(new CommandDefinition(sql,new{TenantId=tenantId,EntidadeId=entidadeId,ExercicioId=exercicioId,r.ProdutorId,r.PropriedadeId,r.MaquinaId,r.ImplementoId,Numero=numero,r.TipoServico,r.DataAgendada,r.ValorEstimado,r.Observacao,UsuarioId=usuarioId,CorrelationId=Guid.NewGuid()},cancellationToken:ct)); await Evento(cn,tenantId,entidadeId,exercicioId,usuarioId,"AgroServicoMaquinaSolicitado","agro_servico_maquina",id,ct); return id;}
    public async Task AtualizarServicoAsync(long tenantId,long entidadeId,long id,long? usuarioId,AgroServicoMaquinaUpdateRequest r,CancellationToken ct){const string sql="update sigov.agro_servico_maquina set propriedade_id=@PropriedadeId,maquina_id=@MaquinaId,implemento_id=@ImplementoId,tipo_servico=@TipoServico,data_agendada=@DataAgendada,valor_estimado=@ValorEstimado,valor_cobrado=@ValorCobrado,status=@Status,observacao=@Observacao,updated_at=now(),updated_by=@UsuarioId where tenant_id=@TenantId and entidade_id=@EntidadeId and id=@Id and is_deleted=false"; using var cn=_context.CreateConnection(); await cn.ExecuteAsync(new CommandDefinition(sql,new{TenantId=tenantId,EntidadeId=entidadeId,Id=id,UsuarioId=usuarioId,r.PropriedadeId,r.MaquinaId,r.ImplementoId,r.TipoServico,r.DataAgendada,r.ValorEstimado,r.ValorCobrado,r.Status,r.Observacao},cancellationToken:ct));}
    public async Task AgendarServicoAsync(long tenantId,long entidadeId,long id,long? exercicioId,long? usuarioId,AgendarServicoMaquinaRequest r,CancellationToken ct){using var cn=_context.CreateConnection(); await cn.ExecuteAsync(new CommandDefinition("update sigov.agro_servico_maquina set maquina_id=@MaquinaId,data_agendada=@DataAgendada,status='AGENDADO',updated_at=now(),updated_by=@UsuarioId where tenant_id=@TenantId and entidade_id=@EntidadeId and id=@Id and is_deleted=false",new{TenantId=tenantId,EntidadeId=entidadeId,Id=id,r.MaquinaId,r.DataAgendada,UsuarioId=usuarioId},cancellationToken:ct)); if(r.DataInicio.HasValue&&r.DataFim.HasValue) await CriarAgendaAsync(tenantId,entidadeId,exercicioId,usuarioId,new AgroAgendaMaquinaCreateRequest(r.MaquinaId,id,r.DataInicio.Value,r.DataFim.Value,"AGENDADA",r.Observacao),ct); await Evento(cn,tenantId,entidadeId,exercicioId,usuarioId,"AgroServicoMaquinaAgendado","agro_servico_maquina",id,ct);}
    public async Task ExecutarServicoAsync(long tenantId,long entidadeId,long id,long? usuarioId,ExecutarServicoMaquinaRequest r,CancellationToken ct){using var cn=_context.CreateConnection(); await cn.ExecuteAsync(new CommandDefinition("update sigov.agro_servico_maquina set data_execucao=@DataExecucao,horas_trabalhadas=@HorasTrabalhadas,area_atendida_ha=@AreaAtendidaHa,horimetro_inicial=@HorimetroInicial,horimetro_final=@HorimetroFinal,odometro_inicial=@OdometroInicial,odometro_final=@OdometroFinal,valor_cobrado=@ValorCobrado,operador_usuario_id=@OperadorUsuarioId,status='EXECUTADO',observacao=coalesce(@Observacao,observacao),updated_at=now(),updated_by=@UsuarioId where tenant_id=@TenantId and entidade_id=@EntidadeId and id=@Id and is_deleted=false",new{TenantId=tenantId,EntidadeId=entidadeId,Id=id,UsuarioId=usuarioId,r.DataExecucao,r.HorasTrabalhadas,r.AreaAtendidaHa,r.HorimetroInicial,r.HorimetroFinal,r.OdometroInicial,r.OdometroFinal,r.ValorCobrado,r.OperadorUsuarioId,r.Observacao},cancellationToken:ct)); await cn.ExecuteAsync(new CommandDefinition("update sigov.agro_maquina m set horimetro_atual=coalesce(@HorimetroFinal,horimetro_atual),odometro_atual=coalesce(@OdometroFinal,odometro_atual),updated_at=now(),updated_by=@UsuarioId from sigov.agro_servico_maquina s where s.maquina_id=m.id and s.tenant_id=m.tenant_id and s.entidade_id=m.entidade_id and s.id=@Id and m.tenant_id=@TenantId and m.entidade_id=@EntidadeId",new{TenantId=tenantId,EntidadeId=entidadeId,Id=id,UsuarioId=usuarioId,r.HorimetroFinal,r.OdometroFinal},cancellationToken:ct)); await Evento(cn,tenantId,entidadeId,null,usuarioId,"AgroServicoMaquinaExecutado","agro_servico_maquina",id,ct);}
    public async Task CancelarServicoAsync(long tenantId,long entidadeId,long id,long? usuarioId,string? motivo,CancellationToken ct){using var cn=_context.CreateConnection(); await cn.ExecuteAsync(new CommandDefinition("update sigov.agro_servico_maquina set status='CANCELADO',observacao=coalesce(@Motivo,observacao),updated_at=now(),updated_by=@UsuarioId where tenant_id=@TenantId and entidade_id=@EntidadeId and id=@Id and is_deleted=false",new{TenantId=tenantId,EntidadeId=entidadeId,Id=id,UsuarioId=usuarioId,Motivo=motivo},cancellationToken:ct)); await Evento(cn,tenantId,entidadeId,null,usuarioId,"AgroServicoMaquinaCancelado","agro_servico_maquina",id,ct);}
    public Task ExcluirServicoAsync(long tenantId,long entidadeId,long id,long? usuarioId,CancellationToken ct)=>Soft("sigov.agro_servico_maquina",tenantId,entidadeId,id,usuarioId,ct);
    public async Task<AgroPatrulhaResumoResponse> ObterResumoAsync(long tenantId,long entidadeId,CancellationToken ct){const string sql="select (select count(*) from sigov.agro_maquina where tenant_id=@TenantId and entidade_id=@EntidadeId and is_deleted=false and ativo and situacao='ATIVA') MaquinasAtivas,(select count(*) from sigov.agro_servico_maquina where tenant_id=@TenantId and entidade_id=@EntidadeId and is_deleted=false and status in ('SOLICITADO','EM_ANALISE')) ServicosPendentes,(select count(*) from sigov.agro_servico_maquina where tenant_id=@TenantId and entidade_id=@EntidadeId and is_deleted=false and status='AGENDADO') ServicosAgendados,(select count(*) from sigov.agro_servico_maquina where tenant_id=@TenantId and entidade_id=@EntidadeId and is_deleted=false and status='EXECUTADO' and date_trunc('month',data_execucao::timestamp)=date_trunc('month',current_date::timestamp)) ServicosExecutadosMes,(select coalesce(sum(horas_trabalhadas),0) from sigov.agro_servico_maquina where tenant_id=@TenantId and entidade_id=@EntidadeId and is_deleted=false and status='EXECUTADO' and date_trunc('month',data_execucao::timestamp)=date_trunc('month',current_date::timestamp)) HorasTrabalhadasMes,(select coalesce(sum(area_atendida_ha),0) from sigov.agro_servico_maquina where tenant_id=@TenantId and entidade_id=@EntidadeId and is_deleted=false and status='EXECUTADO' and date_trunc('month',data_execucao::timestamp)=date_trunc('month',current_date::timestamp)) AreaAtendidaMes"; using var cn=_context.CreateConnection(); return await cn.QuerySingleAsync<AgroPatrulhaResumoResponse>(new CommandDefinition(sql,new{TenantId=tenantId,EntidadeId=entidadeId},cancellationToken:ct));}
    private async Task<PagedResult<T>> Page<T>(string data,string count,long tenantId,long entidadeId,AgroMaquinaFiltro f,CancellationToken ct){using var cn=_context.CreateConnection(); var args=new{TenantId=tenantId,EntidadeId=entidadeId,Situacao=Empty(f.Situacao),Busca=string.IsNullOrWhiteSpace(f.Busca)?null:$"%{f.Busca}%",Limit=f.PageSize,Offset=(f.Page-1)*f.PageSize}; var items=(await cn.QueryAsync<T>(new CommandDefinition(data,args,cancellationToken:ct))).ToArray(); var total=await cn.ExecuteScalarAsync<long>(new CommandDefinition(count,args,cancellationToken:ct)); return new(items,f.Page,f.PageSize,total);}
    private async Task Soft(string table,long tenantId,long entidadeId,long id,long? usuarioId,CancellationToken ct){using var cn=_context.CreateConnection(); await cn.ExecuteAsync(new CommandDefinition($"update {table} set is_deleted=true,ativo=false,deleted_at=now(),deleted_by=@UsuarioId where tenant_id=@TenantId and entidade_id=@EntidadeId and id=@Id and is_deleted=false",new{TenantId=tenantId,EntidadeId=entidadeId,Id=id,UsuarioId=usuarioId},cancellationToken:ct));}
    private static string? Empty(string? v)=>string.IsNullOrWhiteSpace(v)?null:v;
    private static async Task Evento(System.Data.IDbConnection cn,long tenantId,long entidadeId,long? exercicioId,long? usuarioId,string tipo,string origem,long origemId,CancellationToken ct)
    {
        await cn.ExecuteAsync(new CommandDefinition("insert into sigov.agro_evento(tenant_id,entidade_id,exercicio_id,tipo_evento,origem,origem_id,payload_json,created_by,correlation_id) values(@TenantId,@EntidadeId,@ExercicioId,@Tipo,@Origem,@OrigemId,cast(@Payload as jsonb),@UsuarioId,@CorrelationId)",new{TenantId=tenantId,EntidadeId=entidadeId,ExercicioId=exercicioId,Tipo=tipo,Origem=origem,OrigemId=origemId,Payload=JsonSerializer.Serialize(new{tenantId,entidadeId,exercicioId,origem,origemId,tipoEvento=tipo}),UsuarioId=usuarioId,CorrelationId=Guid.NewGuid()},cancellationToken:ct)).ConfigureAwait(false);
    }
}
